const src = `// Counts supplied positions and replays recorded actual moves only.
// No future-sequence search, evaluation, or move selection.
const COLS = "ABCDEFGHJ";
const pt = i => COLS[i % 9] + (Math.floor(i / 9) + 1);
const idx = p => COLS.indexOf(p[0]) + 9 * (Number(p.slice(1)) - 1);
const neighbors = i => [i % 9 ? i - 1 : -1, i % 9 < 8 ? i + 1 : -1, i >= 9 ? i - 9 : -1, i < 72 ? i + 9 : -1].filter(n => n >= 0);
function parse(text) {
  const board = Array(81).fill(".");
  const rows = [...text.matchAll(/^\\s*([1-9])\\s+((?:[XO.]\\s+){8}[XO.])\\s+\\1\\s*$/gm)];
  if (rows.length !== 9) throw Error("Expected nine board rows");
  for (const m of rows) m[2].trim().split(/\\s+/).forEach((c,x) => board[x + 9*(Number(m[1])-1)] = c);
  const caps = text.match(/Captured by Black: (\\d+); by White: (\\d+)/);
  return {board, captures:{X:Number(caps[1]),O:Number(caps[2])}, nextMove:Number(text.match(/Move number: (\\d+)/)[1]), ko:text.match(/Ko point: ([^.]+)\\./)[1]};
}
function component(board, start) {
  const color = board[start], stones = new Set([start]), liberties = new Set(), borders = new Set(), stack=[start];
  while (stack.length) for (const n of neighbors(stack.pop())) {
    if (board[n] === color && !stones.has(n)) { stones.add(n); stack.push(n); }
    else if (board[n] !== color) { borders.add(board[n]); if(board[n] === ".") liberties.add(n); }
  }
  return {color,indices:[...stones],stones:[...stones].map(pt),liberties:[...liberties].map(pt),borders:[...borders]};
}
function inspect(board) {
  const seen = new Set(), groups=[], regions=[], inventory={X:0,O:0,".":0}, area={X:0,O:0,neutral:0};
  for(let i=0;i<81;i++) { inventory[board[i]]++; if(seen.has(i)) continue;
    const c=component(board,i);c.indices.forEach(n=>seen.add(n));
    if(c.color === ".") { regions.push({points:c.stones,borders:c.borders}); if(c.borders.length===1 && ["X","O"].includes(c.borders[0])) area[c.borders[0]]+=c.stones.length; else area.neutral+=c.stones.length; }
    else groups.push({color:c.color,stones:c.stones,liberties:c.liberties});
  }
  area.X+=inventory.X;area.O+=inventory.O;
  return {inventory,groups,regions,area};
}
function replay(moves) {
  const board=Array(81).fill("."), captures={X:0,O:0}; let ko=null; const states=[{board:[...board],captures:{...captures},nextMove:1,ko:"none"}], events=[];
  moves.forEach((m,k) => {
    const color=m.color==="B"?"X":"O",enemy=color==="X"?"O":"X",removed=[];
    if(m.move!=="pass") {
      const i=idx(m.move); if(board[i]!==".")throw Error("Occupied actual move "+(k+1)); if(i===ko)throw Error("Ko actual move "+(k+1));
      board[i]=color;
      for(const n of neighbors(i))if(board[n]===enemy){const g=component(board,n);if(!g.liberties.length){g.indices.forEach(j=>{board[j]=".";removed.push(pt(j));});}}
      const own=component(board,i);if(!own.liberties.length)throw Error("Suicide actual move "+(k+1));
      captures[color]+=removed.length;
      ko=removed.length===1&&own.indices.length===1&&own.liberties.length===1?idx(removed[0]):null;
    } else ko=null;
    if(removed.length)events.push({moveNumber:k+1,color:m.color,move:m.move,captured:removed});
    states.push({board:[...board],captures:{...captures},nextMove:k+2,ko:ko===null?"none":pt(ko)});
  });
  return {states,events};
}
`;
store("g89inspectsrc",src);
const api = (new Function(src+"\nreturn {parse,inspect,replay};"))();
const raw=load("g89raw"), moves=[];
for(const r of raw.filter(r=>r.action==="play")) {
 const s=r.result.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");
 moves.push({color:"B",move:r.move});
 const match=s.match(/Your opponent played ([A-HJ][1-9])\./);
 if(match)moves.push({color:"W",move:match[1]});
 else if(/Your opponent passed\./.test(s))moves.push({color:"W",move:"pass"});
 else throw Error("No opponent move");
}
const replay=api.replay(moves),checks=[];
for(const r of raw){
 const s=r.result.content.filter(c=>c.type==="text").map(c=>c.text).join("\n"),p=api.parse(s),expected=replay.states[p.nextMove-1];
 const ok=JSON.stringify(p)===JSON.stringify(expected);checks.push({action:r.action,position:p.nextMove-1,match:ok});if(!ok)throw Error("Snapshot mismatch "+p.nextMove);
}
const final=api.inspect(replay.states.at(-1).board);
const inspections=[10,24,32,36,38,40,42,44,46,48,52,54].map(position=>({position,inspection:api.inspect(replay.states[position].board),timing:"retrospective"}));
const lost=load("g89target").points.filter(p=>replay.states.at(-1).board["ABCDEFGHJ".indexOf(p[0])+9*(+p.slice(1)-1)]==="O");
store("g89moves",moves);store("g89final",final);store("g89verification",{actualMoves:moves.length,snapshotChecks:checks,captureEvents:replay.events,allSnapshotsMatch:true});store("g89inspections",inspections);store("g89lost",lost);
text({moves:moves.map((m,i)=>`${i+1}${m.color}${m.move}`).join(" "), final,verification:load("g89verification"),lost});

